#include <bits/stdc++.h>
using namespace std;

struct Scanner {
    vector<string> buffer;
    template <class T>
    T next() {
        while (true) {
            if (!buffer.empty()) {
                string token = buffer.back();
                buffer.pop_back();
                stringstream ss(token);
                T value;
                ss >> value;
                return value;
            }
            string input;
            if (!getline(cin, input)) {
                throw runtime_error("Failed read");
            }
            stringstream ss(input);
            string token;
            vector<string> tokens;
            while (ss >> token) tokens.push_back(token);
            buffer.assign(tokens.rbegin(), tokens.rend());
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Scanner scan;
    int n = 4;
    vector<unsigned long long> p(n);
    for (int i = 0; i < n; ++i) {
        p[i] = scan.next<unsigned long long>();
    }
    sort(p.begin(), p.end());
    p.erase(unique(p.begin(), p.end()), p.end());

    cout << n - (int)p.size() << '\n';
    return 0;
}

